// Differential runner: compares the reference executable against node /output/test10.mjs
// Usage: node /tmp/harness/diff.mjs [--verbose] [--only <substr>]
import { spawnSync } from 'node:child_process';
import { cases } from './cases.mjs';

const REF = '/workspace/dataset/test10_executable';
const JS = '/output/test10.mjs';

const argv = process.argv.slice(2);
const verbose = argv.includes('--verbose');
const onlyIdx = argv.indexOf('--only');
const only = onlyIdx >= 0 ? argv[onlyIdx + 1] : null;

function run(cmd, args, env) {
  const r = spawnSync(cmd, args, {
    env: { ...process.env, ...(env || {}) },
    encoding: 'buffer',
    maxBuffer: 64 * 1024 * 1024,
  });
  return {
    code: r.status,
    stdout: (r.stdout || Buffer.alloc(0)).toString('utf8'),
    stderr: (r.stderr || Buffer.alloc(0)).toString('utf8'),
  };
}

// Node prints its own banner/stack for uncaught errors; normalize only the prog name in
// argparse messages if the JS side ever leaks a different prog (it should not).
function show(s) {
  return JSON.stringify(s);
}

let pass = 0;
const failures = [];
for (const c of cases) {
  if (only && !c.name.includes(only)) continue;
  const env = c.env || {};
  const a = run(REF, c.argv, env);
  const b = run(process.execPath, [JS, ...c.argv], env);
  const same = a.code === b.code && a.stdout === b.stdout && a.stderr === b.stderr;
  if (same) {
    pass++;
    if (verbose) console.log(`PASS ${c.name}`);
  } else {
    failures.push({ c, a, b });
    console.log(`FAIL ${c.name}  argv=${JSON.stringify(c.argv)} env=${JSON.stringify(env)}`);
    if (a.code !== b.code) console.log(`  code: ref=${a.code} js=${b.code}`);
    if (a.stdout !== b.stdout) {
      console.log(`  stdout ref=${show(a.stdout)}`);
      console.log(`         js =${show(b.stdout)}`);
    }
    if (a.stderr !== b.stderr) {
      console.log(`  stderr ref=${show(a.stderr)}`);
      console.log(`         js =${show(b.stderr)}`);
    }
  }
}
console.log(`\n${pass} passed, ${failures.length} failed, ${pass + failures.length} total`);
process.exit(failures.length ? 1 : 0);

