import { jwt } from './lib/jose/index.mjs';
import { pyPrint } from './lib/py/print.mjs';

const parser = new ArgumentParser({ prog: 'test10_executable' });
parser.addArgument('--subject', { type: String, required: true });
parser.addArgument('--user_data', { type: String, required: true });
const args = parser.parseArgs();

// Create a token carrying a subject claim.
const secret = 'key';
const payload = new Map([
  ['sub', args.subject],
  ['data', args.user_data],
]);
const token = jwt.encode(payload, secret);
pyPrint(token);

// Decode, validating the subject claim through the options parameter.
const decoded = jwt.decode(token, secret, {
  options: { verify_sub: true },
  algorithms: ['HS256'],
});
pyPrint(decoded);

